#!/bin/bash
# Generate SVD reconstructions of mrco_h5/{test,train} for the full sweep:
#   1D SVD at r = 2, 4, 8, 16, 28
#   2D SVD at r = 2, 4,    16, 28   (r=8 already generated by generate_2d_svd_r8.sh)
#
# Outputs land in subfolders of mrco_h5_svd/ alongside the existing
# 2d_svd_test / 2d_svd_train folders, named:
#   mrco_h5_svd/{mode}_svd_r{rank}_{split}/

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
GENERATOR="${SCRIPT_DIR}/svd_dataset_generator.py"

SRC_ROOT="/sdf/home/m/miaed/tmo_exp/tmo101347625/scratch/miaed_mnis_data/mrco_h5"
DST_ROOT="/sdf/home/m/miaed/tmo_exp/tmo101347625/scratch/miaed_mnis_data/mrco_h5_svd"
PARALLEL=4  # concurrent files per (mode, rank, split)

# (mode rank) pairs to generate. 2d r=8 intentionally skipped.
CONFIGS=(
    "1d 2"
    "1d 4"
    "1d 8"
    "1d 16"
    "1d 28"
    "2d 2"
    "2d 4"
    "2d 16"
    "2d 28"
)

for cfg in "${CONFIGS[@]}"; do
    MODE="${cfg% *}"
    RANK="${cfg#* }"

    for split in test train; do
        src_dir="${SRC_ROOT}/${split}"
        dst_dir="${DST_ROOT}/${MODE}_svd_r${RANK}_${split}"
        mkdir -p "${dst_dir}"

        echo "=== mode=${MODE} rank=${RANK} split=${split}: ${src_dir} -> ${dst_dir} ==="
        shopt -s nullglob
        for f in "${src_dir}"/*.h5; do
            base="$(basename "${f}" .h5)"
            out="${dst_dir}/${base}_svd${MODE}_r${RANK}.h5"
            if [ -e "${out}" ]; then
                echo "  skip (already exists): ${out}"
                continue
            fi
            python3 "${GENERATOR}" \
                --input "${f}" \
                --output-dir "${dst_dir}" \
                --mode "${MODE}" \
                --rank "${RANK}" &
            while (( $(jobs -r | wc -l) >= PARALLEL )); do
                wait -n
            done
        done
        wait
        shopt -u nullglob
    done
done

echo "Done."
